import{_ as r}from"./chunks/9.CNfgUisN.js";import{_ as i}from"./chunks/image2.DiCSfv3Q.js";import{_ as o}from"./chunks/image1.BEPpsZFs.js";import{_ as n,a as s}from"./chunks/image.DnKwf-A0.js";import{_ as l}from"./chunks/image9.D44HCLGC.js";import{_ as c}from"./chunks/image.CsByi7Fr.js";import{_ as d}from"./chunks/image4.AvWkE8iq.js";import{_ as h}from"./chunks/image.BfjhyjBp.js";import{_ as g}from"./chunks/image2.Q-khKGRV.js";import{_ as p}from"./chunks/image.BZc8PBVN.js";import{_ as m}from"./chunks/100.DMbJtyMU.js";import{_ as u}from"./chunks/community.BdKwbEUF.js";import{_,C as b,o as f,c as w,ak as t,E as y}from"./chunks/framework.sbZkgmEx.js";const v="/projects/AiBlock/en/advanced-kit/assets/1.B5v4yBNU.webp",x="/projects/AiBlock/en/advanced-kit/assets/4.D04iT8-r.webp",k="/projects/AiBlock/en/advanced-kit/assets/2.CfpWxddh.webp",V=JSON.parse('{"title":"3.9 Gear Barrier Gate","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Creative Builds/3.9 Gear Barrier Gate.md","filePath":"docs/3.Creative Builds/3.9 Gear Barrier Gate.md"}'),P={name:"docs/3.Creative Builds/3.9 Gear Barrier Gate.md"};function q(T,e,A,C,S,j){const a=b("Pdf");return f(),w("div",null,[e[0]||(e[0]=t('<h1 id="_3-9-gear-barrier-gate" tabindex="-1">3.9 Gear Barrier Gate <a class="header-anchor" href="#_3-9-gear-barrier-gate" aria-label="Permalink to &quot;3.9 Gear Barrier Gate&quot;">​</a></h1><h2 id="_3-9-1-lesson-introduction" tabindex="-1">3.9.1 Lesson Introduction <a class="header-anchor" href="#_3-9-1-lesson-introduction" aria-label="Permalink to &quot;3.9.1 Lesson Introduction&quot;">​</a></h2><p>Modeled after residential barrier gates in daily life, this lesson guides the construction of an ultrasonic-sensing smart barrier gate. The lesson systematically explains gear transmission principles alongside the relationship between tooth count, rotational speed, and torque. Combining a servo with gear mechanisms to raise and lower the barrier arm, it covers button control and automatic proximity sensing through stepped hands-on tasks, helping learners integrate mechanical transmission with intelligent sensing.</p><img loading="lazy" height="1662" width="1662" src="'+r+'" class="common_img" style="width:400px;"><h2 id="_3-9-2-learning-objectives" tabindex="-1">3.9.2 Learning Objectives <a class="header-anchor" href="#_3-9-2-learning-objectives" aria-label="Permalink to &quot;3.9.2 Learning Objectives&quot;">​</a></h2><ol><li><p><strong>Knowledge Objectives</strong>: Understand gear meshing transmission principles. Master how tooth count correlates with speed, torque, and rotational direction. Reinforce servo control and ultrasonic ranging programming skills.</p></li><li><p><strong>Skill Objectives</strong>: Assemble the barrier gate structure and meshing gear train independently. Calibrate the initial home position of the mechanism. Program sensing-based opening routines. Debug gear mesh clearance properly.</p></li><li><p><strong>Thinking Objectives</strong>: Build mechanical thinking centered on gear transmission. Understand power transmission and speed-variation logic. Strengthen intelligent closed-loop control thinking and hardware-software collaborative debugging skills.</p></li><li><p><strong>Application Objectives</strong>: Recognize diverse gear transmission devices in daily life. Understand the essential role of gears in mechanical power transmission to stimulate curiosity about mechanical engineering.</p></li></ol><h2 id="_3-9-3-preparation" tabindex="-1">3.9.3 Preparation <a class="header-anchor" href="#_3-9-3-preparation" aria-label="Permalink to &quot;3.9.3 Preparation&quot;">​</a></h2><h3 id="_1-hardware-preparation" tabindex="-1">(1) Hardware Preparation <a class="header-anchor" href="#_1-hardware-preparation" aria-label="Permalink to &quot;(1) Hardware Preparation&quot;">​</a></h3><ul><li><p>AiBlock controller</p></li><li><p>180° block servo</p></li><li><p>Ultrasonic sensor</p></li><li><p>Building block parts pack</p></li><li><p>Type-C data cable</p></li><li><p>Assembly manual</p></li><li><p>Computer</p></li></ul><h3 id="_2-software-preparation" tabindex="-1">(2) Software Preparation <a class="header-anchor" href="#_2-software-preparation" aria-label="Permalink to &quot;(2) Software Preparation&quot;">​</a></h3><ul><li>WonderLab Graphical Programming Platform</li></ul><h2 id="_3-9-4-hands-on-project" tabindex="-1">3.9.4 Hands-On Project <a class="header-anchor" href="#_3-9-4-hands-on-project" aria-label="Permalink to &quot;3.9.4 Hands-On Project&quot;">​</a></h2><h3 id="_1-project-analysis" tabindex="-1">(1) Project Analysis <a class="header-anchor" href="#_1-project-analysis" aria-label="Permalink to &quot;(1) Project Analysis&quot;">​</a></h3><p>The core project for this lesson is an ultrasonic smart gear barrier gate, creating an automated response that raises the arm when an object approaches and lowers it after departure. The system consists of two main parts: the mechanical subsystem transfers servo torque to the barrier arm through gear transmission, where a smaller driving gear meshes with a larger driven gear to achieve speed reduction and torque multiplication. The sensing subsystem detects distance with an ultrasonic sensor, commanding the servo to rotate to 90° to raise the arm when the distance is under 10 cm, and returning to 0° to lower the arm when the distance exceeds 10 cm. The program uses a combined &quot;loop and dual-branch conditional&quot; structure to demonstrate smart automation combining gear mechanics with sensor feedback.</p><h3 id="_2-assembly-guide" tabindex="-1">(2) Assembly Guide <a class="header-anchor" href="#_2-assembly-guide" aria-label="Permalink to &quot;(2) Assembly Guide&quot;">​</a></h3>',15)),y(a,{src:"../../_static/shared/pdf/chapter_3/9.pdf"}),e[1]||(e[1]=t('<h3 id="_3-hardware-wiring" tabindex="-1">(3) Hardware Wiring <a class="header-anchor" href="#_3-hardware-wiring" aria-label="Permalink to &quot;(3) Hardware Wiring&quot;">​</a></h3><ul><li><p>Connect the 180° block servo to port <strong>S1</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the ultrasonic sensor to port <strong>A</strong> of the controller using a 4-pin module cable.</p></li></ul><img loading="lazy" height="1221" width="1568" src="'+v+'" class="common_img" style="width:500px;"><h3 id="_4-adding-extensions" tabindex="-1">(4) Adding Extensions <a class="header-anchor" href="#_4-adding-extensions" aria-label="Permalink to &quot;(4) Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Ultrasonic sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+i+'" class="common_img" style="width:800px;"><ul><li>Select <strong>180° servo</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+o+'" class="common_img" style="width:800px;"><h3 id="_5-core-blocks" tabindex="-1">(5) Core Blocks <a class="header-anchor" href="#_5-core-blocks" aria-label="Permalink to &quot;(5) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="257" width="228" src="'+n+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="108" src="'+s+'"></td><td style="text-align:left;">Compares two values and returns a true or false result</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="193" width="589" src="'+l+'"></td><td style="text-align:center;"><img loading="lazy" height="95" width="108" src="'+c+'"></td><td style="text-align:left;">Triggers corresponding blocks when the button is short-pressed</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="65" width="625" src="'+d+'"></td><td style="text-align:center;"><img loading="lazy" height="95" width="108" src="'+h+'"></td><td style="text-align:left;">Rotates the specified servo to a target angle at a set speed</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="48" width="304" src="'+g+'"></td><td style="text-align:center;"><img loading="lazy" height="80" width="99" src="'+p+'"></td><td style="text-align:left;">Obtains the obstacle distance detected by the ultrasonic sensor</td></tr></tbody></table><h3 id="_6-program-description-and-upload" tabindex="-1">(6) Program Description and Upload <a class="header-anchor" href="#_6-program-description-and-upload" aria-label="Permalink to &quot;(6) Program Description and Upload&quot;">​</a></h3><ul><li>Program Schematic</li></ul><img loading="lazy" height="721" width="430" src="'+x+'" class="common_img" style="width:400px;"><ul><li><p>Complete Program</p><ol><li><p>When executing the main program after powering on, it first initializes the ultrasonic sensor on port A, then enters a continuous repeat loop to poll distance data in real time:</p><ul><li><p>When obstacle distance is under 10 cm, servo S1 rotates without delay to 90° at 40% speed, then waits 1 s.</p></li><li><p>When obstacle distance is greater than or equal to 10 cm, servo S1 rotates without delay to 0° at 40% speed, then waits 1 s.</p></li></ul></li><li><p>Independent button control logic allows manually overriding the servo position:</p><ul><li><p>Short-pressing the left button rotates servo S1 without delay to 0° at 40% speed.</p></li><li><p>Short-pressing the right button rotates servo S1 without delay to 90° at 40% speed.</p></li></ul></li></ol></li></ul><img loading="lazy" height="736" width="656" src="'+k+'" class="common_img" style="width:500px;"><ul><li><p>Program Upload</p><p>Following the animation, click <strong>Connect device</strong>, select the serial port, then click the upload button to upload the program to the controller and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+m+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1xyD_-3msc3KcaGQHLqkcPOZNSNXFIirT?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-9-5-expansion-and-challenge" tabindex="-1">3.9.5 Expansion and Challenge <a class="header-anchor" href="#_3-9-5-expansion-and-challenge" aria-label="Permalink to &quot;3.9.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Delayed Lowering Barrier Gate</strong></p><p>Optimize barrier logic: upon raising the gate after detecting an approaching vehicle, keep the arm open for 3 s before lowering, simulating real community barrier gates that wait for cars to clear completely before closing. Use a variable to track whether the arm has already been raised, avoiding redundant trigger cycles. Practice state retention and timed delays to make the barrier system more reliable and authentic.</p><p><strong>Project 2: Two-Way Counting Gate</strong></p><p>Add vehicle counting: increment a counter variable by 1 each time the gate opens to track total traffic volume. Utilize onboard RGB lights or the buzzer to issue audiovisual feedback upon each passage. This exercises variable arithmetic and multi-task programming, upgrading the simple barrier into an intelligent access gate with automated logging.</p><h2 id="_3-9-6-q-a" tabindex="-1">3.9.6 Q&amp;A <a class="header-anchor" href="#_3-9-6-q-a" aria-label="Permalink to &quot;3.9.6 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: What are the key characteristics of gear transmission? How do gears transfer mechanical power?</strong></p><p>Answer: Gear transmission features several defining principles. First is <strong>positive meshing</strong>: teeth of paired gears interlock securely, so when the driving gear rotates, its teeth push the teeth of the driven gear to transfer power directly without slipping. Second is <strong>counter-rotation</strong>: two meshing external gears rotate in opposite directions, with clockwise rotation on one producing counter-clockwise rotation on the other. Third is <strong>speed and torque transformation by tooth ratio</strong>: a small gear driving a large gear reduces speed while increasing torque, whereas a large gear driving a small gear increases speed while reducing torque. Fourth is <strong>precise transmission ratio</strong>: gear engagement prevents slip, maintaining exact rotational synchronization. This barrier gate uses a smaller gear to drive a larger gear, generating the mechanical torque necessary to lift the heavy barrier arm smoothly.</p><p><strong>Question 2: How does the automatic ultrasonic gate program operate? Why is a repeat loop required?</strong></p><p>Answer: The automated gate program follows a classic architecture: initialization, loop polling, conditional evaluation, and action execution. The program first initializes the ultrasonic sensor to prepare the hardware. It then enters a continuous repeat loop to evaluate conditions: if the distance is under 10 cm, indicating an approaching vehicle, the servo turns to 90° to raise the gate. When distance exceeds 10 cm, the servo turns to 0° to close the gate. Each movement includes a 1 s pause to prevent jitter and erratic toggling. A continuous repeat loop is essential because the gate must stand guard continuously and react at any moment. If evaluated only once, the program would terminate, missing subsequent vehicles. Running inside a loop checks sensor data multiple times every second, delivering real-time responsiveness characteristic of all automated sensing systems.</p><h2 id="_3-9-7-technical-support-and-product-discussion" tabindex="-1">3.9.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-9-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.9.7 Technical Support and Product Discussion&quot;">​</a></h2><p>To share creative ideas and projects after exploring this kit, visit the Hiwonder Community:</p><a href="https://forum.hiwonder.com/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+u+'" class="common_img" style="width:800px;"></a>',31))])}const F=_(P,[["render",q]]);export{V as __pageData,F as default};
